// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    address deployer;
    function setUp() public {
        deployer = address(this);
        c = new ERCDDAToken(1000000, "Token", "TKN");
    }
    function testFuzz_property(address thief, uint256 burnAmount) public {
        vm.assume(thief != address(0));
        vm.assume(thief != deployer);
        vm.assume(burnAmount <= 1000000 * 10**uint256(c.decimals()));
        vm.prank(thief);
        try c.owned() {} catch {}
        vm.prank(thief);
        bool ok = true;
        try c.burn(burnAmount) { ok = true; } catch { ok = false; }
        if (ok) {
            assertEq(c.owner(), deployer);
        } else {
            assertTrue(true);
        }
    }
}
